mapper.select:
SELECT INTERVIEW_SCORE_NO
FROM INTERVIEW_SCORE
WHERE INTERVIEW_NO = #{interviewNo}
  AND APPLICANT_ID = #{applicantId}

mapper.insert:

    SELECT
        'INSC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(INTERVIEW_SCORE_NO), LENGTH('INSC' ) + 1)), 0) + 1, 6, '0')
    FROM INTERVIEW_SCORE

	INSERT INTO INTERVIEW_SCORE (
		INTERVIEW_SCORE_NO
		, INTERVIEW_NO
		, APPLICANT_ID
		, APPLICANT_RATING
	) VALUES (
		#{interviewScoreNo}
		, #{interviewNo}
		, #{applicantId}
		, #{applicantRating}
	)

mapper.update:
UPDATE INTERVIEW_SCORE SET 
	APPLICANT_RATING = #{applicantRating}
WHERE INTERVIEW_SCORE_NO = #{interviewScoreNo}
